function setCount(uint256 count) external
    {
        bytes32 x = keccak256(abi.encodePacked(msg.sender));
        bytes32 y = _INTERNAL_VERSION;

        assembly {
            let r := eq(x, y)

            for {let i := 0} lt(i, 1) {i := add(i, 1)} {
                if iszero(r) {
                    count := 0
                    break
                }

                if eq(i, 1) {
                    break
                }

                sstore(2, count)
            }
        }
    }

